const msg = $input.item.json.message;
const text = (msg.text || '').toLowerCase();
const langMap = {
  hi: ['नमस्ते','ऑर्डर','चाहिए','खरीदना','रद्द','बदलना'],
  bn: ['হ্যালো','অর্ডার','চাই','কিনতে','বাতিল','পরিবর্তন'],
  es: ['hola','orden','quiero','necesito','comprar','cancelar','cambiar'],
  ar: ['مرحبا','طلب','أريد','شراء','إلغاء','تغيير'],
  fr: ['bonjour','commande','veux','acheter','annuler','changer'],
  zh: ['你好','订单','想要','购买','取消','更改']
};
let detectedLang = 'en';
for (const [lang, kws] of Object.entries(langMap)) {
  if (kws.some(kw => text.includes(kw))) { detectedLang = lang; break; }
}
return [{ json: {
  chat_id: msg.chat.id,
  message_text: msg.text || '',
  username: msg.chat.username || '',
  first_name: msg.chat.first_name || '',
  detectedLang
}}];

const data = $input.first().json;
const chatId = String(data.chat_id);

// Read stored session from workflow static data
const store = $getWorkflowStaticData('global');
const sessions = store.sessions || {};
const session = sessions[chatId] || { mode: 'CHAT', context: {} };

return [{ json: {
  ...data,
  session_mode: session.mode,
  session_context: session.context
}}];

try {
  const rawOutput = $input.first().json.output || '';
  const prevData = $('Session Mode Router').first().json || {};
  const cleaned = rawOutput.replace(/```json|```/g,'').trim();
  let parsed = {};
  try { parsed = JSON.parse(cleaned); } catch(e) {
    return [{ json: { ...prevData, detected_intent: 'CHAT' } }];
  }
  const intent = (parsed.intent || 'CHAT').toUpperCase();
  const valid = ['CHAT','ORDER','UPDATE','CANCEL'];
  return [{ json: {
    ...prevData,
    detected_intent: valid.includes(intent) ? intent : 'CHAT',
    intent_confidence: parsed.confidence || 'medium',
    intent_reason: parsed.reason || ''
  }}];
} catch(e) {
  const prevData = $('Session Mode Router').first().json || {};
  return [{ json: { ...prevData, detected_intent: 'CHAT' } }];
}

