try {
  const rawOutput = $input.first().json.output || '';
  const prevData = $('Session Mode Router').first().json || {};
  const cleaned = (typeof rawOutput === 'string' ? rawOutput : JSON.stringify(rawOutput)).replace(/```json|```/g,'').trim();

  if (!cleaned.startsWith('{')) {
    return [{ json: { __is_complete: false, chat_id: prevData.chat_id, reply_text: cleaned, session_mode: prevData.session_mode } }];
  }

  let orderData = {};
  try { orderData = JSON.parse(cleaned); } catch(e) {
    return [{ json: { __is_complete: false, chat_id: prevData.chat_id, reply_text: rawOutput, session_mode: prevData.session_mode } }];
  }

  if (!orderData.product_name || !orderData.quantity || !orderData.customer_name ||
      !orderData.delivery_address || !orderData.phone_number || !orderData.email) {
    return [{ json: { __is_complete: false, chat_id: prevData.chat_id, reply_text: rawOutput, session_mode: prevData.session_mode } }];
  }

  return [{ json: {
    __is_complete: true,
    chat_id: prevData.chat_id,
    username: prevData.username,
    first_name: prevData.first_name,
    detectedLang: prevData.detectedLang,
    message_text: prevData.message_text,
    product_name: orderData.product_name,
    quantity: orderData.quantity,
    customer_name: orderData.customer_name,
    delivery_address: orderData.delivery_address,
    phone_number: orderData.phone_number,
    email: orderData.email
  }}];
} catch(error) {
  const prevData = $('Session Mode Router').first().json || {};
  return [{ json: { __is_complete: false, chat_id: prevData.chat_id, reply_text: 'Sorry, something went wrong. Please try again.', session_mode: prevData.session_mode } }];
}

