try {
  const rawOutput = $input.first().json.output || '';
  const prevData = $('Session Mode Router').first().json || {};
  const cleaned = rawOutput.replace(/```json|```/g,'').trim();
  let parsed = {};
  try { parsed = JSON.parse(cleaned); } catch(e) {
    return [{ json: { ...prevData, __needs_more_info: true, ask_message: 'Could you clarify what you would like to change?' } }];
  }
  if (parsed.needs_more_info) {
    return [{ json: { ...prevData, __needs_more_info: true, ask_message: parsed.ask_message } }];
  }
  return [{ json: { ...prevData, __needs_more_info: false, field_to_update: parsed.field_to_update, new_value: parsed.new_value, order_id: parsed.order_id } }];
} catch(e) {
  const prevData = $('Session Mode Router').first().json || {};
  return [{ json: { ...prevData, __needs_more_info: true, ask_message: 'Could you clarify what you would like to change?' } }];
}

const updateData = $('Parse Update Request').first().json;
const orderRow = $input.first().json;
if (!orderRow || !orderRow.order_id) {
  return [{ json: { ...updateData, __no_order_found: true } }];
}
return [{ json: { ...updateData, found_order_id: orderRow.order_id, existing_order: orderRow } }];

