const lang = data.detectedLang || 'en';
const templates = {
  en: `✅ Your order has been updated!\nOrder ID: ${data.found_order_id}\nChanged: ${data.field_to_update} → ${data.new_value}`,
  hi: `✅ आपका ऑर्डर अपडेट हो गया!\nऑर्डर आईडी: ${data.found_order_id}\nबदला: ${data.field_to_update} → ${data.new_value}`,
  bn: `✅ আপনার অর্ডার আপডেট হয়েছে!\nঅর্ডার আইডি: ${data.found_order_id}`,
  es: `✅ ¡Su pedido ha sido actualizado!\nID: ${data.found_order_id}`,
  ar: `✅ تم تحديث طلبك!\nمعرف الطلب: ${data.found_order_id}`,
  fr: `✅ Votre commande a été mise à jour!\nID: ${data.found_order_id}`,
  zh: `✅ 您的订单已更新！\n订单编号: ${data.found_order_id}`
};
return [{ json: { ...data, confirmMessage: templates[lang] || templates.en } }];

const item = $input.first().json;
